25	func TestPreviewTriggerRecoveryAndReTrigger(t *testing.T) {
26		tl := NewTimeline()
27		// Five 60s windows; threshold 2, trigger 2, recover 1.
28		at := func(w, offset int) time.Time { return alertTime(float64(w*60 + offset)) }
29		seedAlerts(t, tl, []Event{
30			mustEvent("a1", "s", at(0, 5), nil), mustEvent("a2", "s", at(0, 30), nil),
31			mustEvent("b1", "s", at(1, 5), nil), mustEvent("b2", "s", at(1, 40), nil),
32			// w2 empty: recovery.
33			mustEvent("d1", "s", at(3, 10), nil), mustEvent("d2", "s", at(3, 20), nil),
34			mustEvent("e1", "s", at(4, 10), nil), mustEvent("e2", "s", at(4, 59), nil),
35		})
36	
37		result, err := tl.PreviewAlerts(AlertPreviewQuery{
38			Since: alertTime(0), Until: alertTime(300), Window: time.Minute,
39			Threshold: 2, TriggerWindows: 2, RecoverWindows: 1,
40		})
41		if err != nil {
42			t.Fatalf("preview: %v", err)
43		}
44		if len(result.Groups) != 1 {
45			t.Fatalf("one service => one group, got %d", len(result.Groups))
46		}
47		group := result.Groups[0]
48		if len(group.Windows) != 5 {
49			t.Fatalf("five windows, got %d", len(group.Windows))
50		}
51		wantStatus := []string{
52			AlertStatusNormal,   // w0: trigger run 1
53			AlertStatusAlerting, // w1: opens at 10:02
54			AlertStatusNormal,   // w2: one quiet window recovers at 10:03
55			AlertStatusNormal,   // w3: trigger run restarts
56			AlertStatusAlerting, // w4: reopens at range end, unresolved
57		}
58		for i, window := range group.Windows {
59			if window.Status != wantStatus[i] {
60				t.Fatalf("w%d status = %s, want %s", i, window.Status, wantStatus[i])
61			}
62		}
63		if group.Windows[2].Count != 0 {
64			t.Fatalf("empty window must be zero-filled, got %d", group.Windows[2].Count)
65		}
66		// The 10:04:59 event stays inside the range; the last window is short of
67		// nothing here (range is exactly five minutes), so verify counts.
68		if group.Windows[4].Count != 2 {
69			t.Fatalf("w4 count = %d", group.Windows[4].Count)
70		}
71	
72		if len(group.Alerts) != 2 {
73			t.Fatalf("two alert cycles, got %d: %+v", len(group.Alerts), group.Alerts)
74		}
75		first := group.Alerts[0]
76		if !first.OpenedAt.Equal(alertTime(120)) {
77			t.Fatalf("first opens at end of w1 (10:02), got %s", first.OpenedAt)
78		}
79		if first.RecoveredAt == nil || !first.RecoveredAt.Equal(alertTime(180)) {
80			t.Fatalf("first recovers at end of w2 (10:03), got %v", first.RecoveredAt)
81		}
82		second := group.Alerts[1]
83		if !second.OpenedAt.Equal(alertTime(300)) || second.RecoveredAt != nil {
84			t.Fatalf("second opens at range end and stays open, got %+v", second)
85		}
86	}
87	
88	func TestPreviewConsecutiveRunsReset(t *testing.T) {
89		tl := NewTimeline()
90		at := func(w int) time.Time { return alertTime(float64(w * 60)) }
91		// threshold 1, trigger 2: w0 met, w1 quiet (reset), w2 met, w3 met opens.
92		seedAlerts(t, tl, []Event{
93			mustEvent("a", "s", at(0).Add(5*time.Second), nil),
94			mustEvent("c", "s", at(2).Add(5*time.Second), nil),
95			mustEvent("d", "s", at(3).Add(5*time.Second), nil),
96		})
97		result, err := tl.PreviewAlerts(AlertPreviewQuery{
98			Since: alertTime(0), Until: alertTime(300), Window: time.Minute,
99			Threshold: 1, TriggerWindows: 2, RecoverWindows: 2,
100		})
101		if err != nil {
102			t.Fatalf("preview: %v", err)
103		}
104		statuses := result.Groups[0].Windows
105		for i, want := range []string{
106			AlertStatusNormal, AlertStatusNormal, AlertStatusNormal, AlertStatusAlerting, AlertStatusAlerting,
107		} {
108			if statuses[i].Status != want {
109				t.Fatalf("w%d = %s, want %s", i, statuses[i].Status, want)
110			}
111		}
112	
113		// Recovery run resets when a threshold-meeting window interrupts it:
114		// trigger w0,w1 opens; w2 quiet (run 1), w3 met again (reset), w4 quiet
115		// (run 1 only) => still alerting at the end, never recovered.
116		tl = NewTimeline()
117		seedAlerts(t, tl, []Event{
118			mustEvent("a", "s", at(0).Add(5*time.Second), nil),
119			mustEvent("b", "s", at(1).Add(5*time.Second), nil),
120			mustEvent("d", "s", at(3).Add(5*time.Second), nil),
121		})
122		result, err = tl.PreviewAlerts(AlertPreviewQuery{
123			Since: alertTime(0), Until: alertTime(300), Window: time.Minute,
124			Threshold: 1, TriggerWindows: 2, RecoverWindows: 2,
125		})
126		if err != nil {
127			t.Fatalf("preview: %v", err)
128		}
129		group := result.Groups[0]
130		statuses = group.Windows
131		want := []string{
132			AlertStatusNormal, AlertStatusAlerting, AlertStatusAlerting, AlertStatusAlerting, AlertStatusAlerting,
133		}
134		for i := range want {
135			if statuses[i].Status != want[i] {
136				t.Fatalf("w%d = %s, want %s", i, statuses[i].Status, want[i])
137			}
138		}
139		if len(group.Alerts) != 1 || group.Alerts[0].RecoveredAt != nil {
140			t.Fatalf("interrupted recovery must not close the alert: %+v", group.Alerts)
141		}
142	}
143	
144	func TestPreviewDoesNotReopenWhileAlerting(t *testing.T) {
145		tl := NewTimeline()
146		at := func(w int) time.Time { return alertTime(float64(w*60 + 5)) }
147		seedAlerts(t, tl, []Event{
148			mustEvent("a", "s", at(0), nil), mustEvent("b", "s", at(1), nil),
149			mustEvent("c", "s", at(2), nil), mustEvent("d", "s", at(3), nil),
150			mustEvent("e", "s", at(4), nil),
151		})
152		result, err := tl.PreviewAlerts(AlertPreviewQuery{
153			Since: alertTime(0), Until: alertTime(300), Window: time.Minute,
154			Threshold: 1, TriggerWindows: 2, RecoverWindows: 1,
155		})
156		if err != nil {
157			t.Fatalf("preview: %v", err)
158		}
159		alerts := result.Groups[0].Alerts
160		if len(alerts) != 1 || alerts[0].RecoveredAt != nil {
161			t.Fatalf("continued threshold hits must not reopen: %+v", alerts)
162		}
163	}
164	
165	func TestPreviewHalfOpenRangeAndShortLastWindow(t *testing.T) {
166		tl := NewTimeline()
167		// Range 10:00:00..10:02:30 with 60s windows: three windows (60, 60, 30).
168		// An event at exactly until is excluded; an event at since lands in w0.
169		seedAlerts(t, tl, []Event{
170			mustEvent("start", "s", alertTime(0), nil),
171			mustEvent("end", "s", alertTime(150), nil),
172			mustEvent("tail", "s", alertTime(149.5), nil),
173		})
174		result, err := tl.PreviewAlerts(AlertPreviewQuery{
175			Since: alertTime(0), Until: alertTime(150), Window: time.Minute,
176			Threshold: 1, TriggerWindows: 1, RecoverWindows: 1,
177		})
178		if err != nil {
179			t.Fatalf("preview: %v", err)
180		}
181		windows := result.Groups[0].Windows
182		if len(windows) != 3 {
183			t.Fatalf("three windows including the short tail, got %d", len(windows))
184		}
185		if !windows[2].End.Equal(alertTime(150)) {
186			t.Fatalf("last window ends at range end, got %s", windows[2].End)
187		}
188		if windows[0].Count != 1 || windows[1].Count != 0 || windows[2].Count != 1 {
189			t.Fatalf("half-open counts wrong: %d %d %d", windows[0].Count, windows[1].Count, windows[2].Count)
190		}
191	}
192	
193	func TestPreviewGroupingByLabelsWithNullFirst(t *testing.T) {
194		tl := NewTimeline()
195		seed := func(id, service string, w int, labels map[string]string) {
196			seedAlerts(t, tl, []Event{mustEvent(id, service, alertTime(float64(w*60+5)), labels)})
197		}
198		seed("g1", "gateway", 0, map[string]string{"env": "prod"})
199		seed("g2", "gateway", 0, map[string]string{"env": "dev"})
200		seed("g3", "gateway", 0, nil) // missing env
201		seed("g4", "api", 0, map[string]string{"env": "prod"})
202		seed("g5", "api", 0, map[string]string{"env": "prod", "region": "cn"}) // group env only: still prod
203	
204		result, err := tl.PreviewAlerts(AlertPreviewQuery{
205			Since: alertTime(0), Until: alertTime(120), Window: time.Minute,
206			Threshold: 1, TriggerWindows: 1, RecoverWindows: 1,
207			GroupLabels: []string{"env"},
208		})
209		if err != nil {
210			t.Fatalf("preview: %v", err)
211		}
212		if len(result.GroupLabelNames) != 1 || result.GroupLabelNames[0] != "env" {
213			t.Fatalf("group names: %v", result.GroupLabelNames)
214		}
215		// api/prod, gateway/null, gateway/dev, gateway/prod — service first, then
216		// null before strings, strings ascending.
217		want := []struct {
218			service string
219			value   *string
220		}{
221			{"api", strPtr("prod")},
222			{"gateway", nil},
223			{"gateway", strPtr("dev")},
224			{"gateway", strPtr("prod")},
225		}
226		if len(result.Groups) != len(want) {
227			t.Fatalf("got %d groups, want %d", len(result.Groups), len(want))
