314	func TestPreviewValidation(t *testing.T) {
315		base := func() AlertPreviewQuery {
316			return AlertPreviewQuery{
317				Since: alertTime(0), Until: alertTime(60), Window: time.Minute,
318				Threshold: 1, TriggerWindows: 1, RecoverWindows: 1,
319			}
