321		cases := map[string]func(AlertPreviewQuery) AlertPreviewQuery{
322			"inverted range": func(q AlertPreviewQuery) AlertPreviewQuery {
323				q.Since, q.Until = q.Until, q.Since
324				return q
325			},
326			"zero length range": func(q AlertPreviewQuery) AlertPreviewQuery {
327				q.Until = q.Since
328				return q
329			},
330			"window zero": func(q AlertPreviewQuery) AlertPreviewQuery {
331				q.Window = 0
332				return q
333			},
334			"window fractional": func(q AlertPreviewQuery) AlertPreviewQuery {
335				q.Window = time.Second + time.Nanosecond
336				return q
337			},
338			"window too large": func(q AlertPreviewQuery) AlertPreviewQuery {
339				q.Window = 86401 * time.Second
340				return q
341			},
342			"threshold zero": func(q AlertPreviewQuery) AlertPreviewQuery {
343				q.Threshold = 0
344				return q
345			},
346			"threshold too large": func(q AlertPreviewQuery) AlertPreviewQuery {
347				q.Threshold = 1000001
348				return q
349			},
350			"trigger zero": func(q AlertPreviewQuery) AlertPreviewQuery {
351				q.TriggerWindows = 0
352				return q
353			},
354			"recover too large": func(q AlertPreviewQuery) AlertPreviewQuery {
355				q.RecoverWindows = 101
356				return q
357			},
358			"too many group labels": func(q AlertPreviewQuery) AlertPreviewQuery {
359				q.GroupLabels = []string{"a", "b", "c", "d", "e"}
360				return q
361			},
362		}
363		wantErr := map[string]error{
364			"inverted range":        ErrAlertRange,
365			"zero length range":     ErrAlertRange,
366			"window zero":           ErrAlertWindow,
367			"window fractional":     ErrAlertWindow,
368			"window too large":      ErrAlertWindow,
369			"threshold zero":        ErrAlertThreshold,
370			"threshold too large":   ErrAlertThreshold,
371			"trigger zero":          ErrAlertConsecutive,
372			"recover too large":     ErrAlertConsecutive,
373			"too many group labels": ErrAlertGroupLabels,
374		}
375		tl := NewTimeline()
376		for name, mutate := range cases {
377			t.Run(name, func(t *testing.T) {
378				_, err := tl.PreviewAlerts(mutate(base()))
379				if !errors.Is(err, wantErr[name]) {
380					t.Fatalf("got %v, want %v", err, wantErr[name])
381				}
382			})
383		}
384	
385		// Window-count limit: exactly 10000 one-second windows is allowed; one
386		// nanosecond more needs 10001 windows and is rejected.
387		ok := base()
388		ok.Since = alertTime(0)
389		ok.Until = alertTime(10000)
390		ok.Window = time.Second
391		if _, err := tl.PreviewAlerts(ok); err != nil {
392			t.Fatalf("10000 windows must be allowed: %v", err)
393		}
394		over := ok
395		over.Until = alertTime(10000).Add(time.Nanosecond)
396		if _, err := tl.PreviewAlerts(over); !errors.Is(err, ErrAlertTooManyWindows) {
397			t.Fatalf("10001 windows: got %v, want ErrAlertTooManyWindows", err)
398		}
