169	func httpDo(t *testing.T, method, url, body string) (int, []byte) {
170		t.Helper()
171		var reader io.Reader
172		if body != "" {
173			reader = strings.NewReader(body)
174		}
175		req, err := http.NewRequest(method, url, reader)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if body != "" {
180			req.Header.Set("Content-Type", "application/json")
181		}
182		resp, err := http.DefaultClient.Do(req)
183		if err != nil {
184			t.Fatalf("%s %s: %v", method, url, err)
185		}
186		defer resp.Body.Close()
187		raw, err := io.ReadAll(resp.Body)
188		if err != nil {
189			t.Fatal(err)
190		}
191		return resp.StatusCode, raw
192	}
