239	func TestServePersistsAcrossKillAndDedupesRetry(t *testing.T) {
240		dataDir := t.TempDir()
241		p := startServer(t, dataDir)
242		counts := postEvents(t, p, sampleEvents)
243		if counts["created"] != 2 {
244			t.Fatalf("created=%d", counts["created"])
245		}
246	
247		// Hard kill: no graceful shutdown, fsync had already confirmed durability.
248		p.signal(t, syscall.SIGKILL)
249		p.waitExit(t, -1) // killed by signal
250		waitTCPPortClosed(t, p.addr)
251	
252		p2 := startServer(t, dataDir)
253		got := getEvents(t, p2, "")
254		if len(got) != 2 || got[0]["id"] != "e1" {
255			t.Fatalf("recovery after SIGKILL: %+v", got)
256		}
257	
258		// Retry of the fully confirmed batch dedupes after restart.
259		retry := postEvents(t, p2, sampleEvents)
260		if retry["created"] != 0 || retry["replayed"] != 2 {
261			t.Fatalf("retry after restart: %+v", retry)
262		}
263		if len(getEvents(t, p2, "")) != 2 {
264			t.Fatal("replayed retry must not duplicate events")
265		}
266	
267		p2.signal(t, syscall.SIGTERM)
268		p2.waitExit(t, 0) // graceful shutdown exits cleanly
269	}
