// ensureSlowScan grows the timeline with irrelevant events until one preview
// scan takes long enough that another goroutine can queue against its read
// lock. The filler events belong to a different service and fall outside the
// scenario range, so they never change a preview result; they only widen the
// window in which ingestion and the preview overlap.
func ensureSlowScan(t *testing.T, tl *Timeline, query AlertPreviewQuery) time.Duration {
	t.Helper()
	base := scenarioAnchor().AddDate(0, -1, 0)
	scan := func() time.Duration {
		start := time.Now()
		if _, err := tl.PreviewAlerts(query); err != nil {
			t.Fatalf("warmup preview: %v", err)
		}
		return time.Since(start)
	}
	total := 0
	for round := 0; round < 8; round++ {
		const chunk = 100000
		fillers := make([]Event, 0, chunk)
		for i := range chunk {
			fillers = append(fillers, Event{
				ID:       "filler-" + itoa(total+i),
				Service:  "filler-svc",
				Severity: "info",
				Message:  "m",
				At:       base.Add(time.Duration(total+i) * time.Nanosecond),
			})
		}
