}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

// TestPreviewOverlappingBatchCommitIsOneSnapshot runs previews while a batch
// submission is in flight and then while its commit is held pending (write
// lock held, durable write unfinished). A preview that completes before the
// commit is released must show the complete pre-batch observation; previews
// blocked on the pending write lock must all show the complete post-batch
// observation. A half-applied batch, mixed group snapshots, or a
// counts/status/alerts mismatch fails the regression.
func TestPreviewOverlappingBatchCommitIsOneSnapshot(t *testing.T) {
	tl := NewTimeline()
	query := scenarioQuery()
	seedScenarioOldData(t, tl)

	before, err := tl.PreviewAlerts(query)
	if err != nil {
		t.Fatalf("preview before: %v", err)
	}

	// Make one scan observably slow, then start that slow preview before the
	// submission begins. The writer either queues behind the preview's read
	// lock or reaches the held hook; either way the preview cannot see any of
	// the new events, because the batch becomes visible only once the hook
	// returns (which happens after this preview response is consumed).
	scanTime := ensureSlowScan(t, tl, query)
	earlyDone := make(chan AlertPreviewResult, 1)
	go func() {
		result, err := tl.PreviewAlerts(query)
		if err != nil {
			t.Errorf("early preview: %v", err)
			return
		}
		earlyDone <- result
	}()
	time.Sleep(scanTime / 2)

	entered := make(chan struct{})
	release := make(chan struct{})
	commitDone := make(chan IngestResult, 1)
	go func() {
		result, err := tl.Ingest(scenarioBatch(), func(persisted []Event) error {
			close(entered)
			<-release
			return nil
		})
		if err != nil {
			t.Errorf("blocked ingest: %v", err)
		}
		commitDone <- result
	}()

	early := <-earlyDone
	if !reflect.DeepEqual(early, before) {
		t.Fatalf("preview finishing while the submission is in flight must stay pre-batch:\n%+v", summarizePreview(early))
	}
	<-entered

	const readers = 24
	observed := make([]AlertPreviewResult, readers)
	var wg sync.WaitGroup
	for i := range readers {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			result, err := tl.PreviewAlerts(query)
			if err != nil {
				t.Errorf("concurrent preview %d: %v", i, err)
				return
			}
			observed[i] = result
		}(i)
	}
	// Let the preview goroutines queue on the write lock while the commit is
	// still pending.
	time.Sleep(20 * time.Millisecond)
	close(release)
	ingest := <-commitDone
	if ingest.Created != 5 {
		t.Fatalf("batch created=%d, want 5", ingest.Created)
	}
	wg.Wait()

	after, err := tl.PreviewAlerts(query)
	if err != nil {
		t.Fatalf("preview after: %v", err)
	}
	assertScenarioAfter(t, after)
	if reflect.DeepEqual(before, after) {
		t.Fatal("pre- and post-batch observations must differ")
	}
	for i, result := range observed {
		assertPreviewCoherent(t, query, result)
		if !reflect.DeepEqual(result, after) {
			t.Fatalf("preview %d queued behind the pending commit must show the full post-batch state:\n%+v",
				i, summarizePreview(result))
		}
	}
}

