		}
		counts := make([]int, len(group.Windows))
		for i, window := range group.Windows {
			counts[i] = window.Count
		}
		summary = append(summary, struct {
			group  string
			counts []int
			alerts []AlertRecord
		}{name, counts, group.Alerts})
	}
	return summary
}

